final class CannotFindRelativePosition
{
    private function __construct(
        public string $variant,
        public array $fields = [],
    ) {
    }
    public static function containerDeleted(string $message): self
    {
        return new self('ContainerDeleted', ['message' => $message]);
    }
    public static function historyCleared(string $message): self
    {
        return new self('HistoryCleared', ['message' => $message]);
    }
    public static function idNotFound(string $message): self
    {
        return new self('IdNotFound', ['message' => $message]);
    }
    public static function uniffiLift(\FFI\CData $buf): self
    {
        return UniFFIRuntime::liftSerialized($buf, ['enum', self::class]);
    }

    public static function uniffiLower(self $value): \FFI\CData
    {
        return UniFFIRuntime::lowerSerialized($value, ['enum', self::class]);
    }

    public static function uniffiRead(array &$reader): self
    {
        $variant = UniFFIRuntime::readInt32($reader);
        switch ($variant) {
            case 1: return self::containerDeleted(UniFFIRuntime::readValue($reader, 'string'));
